for(const j of items)for(const [dx,dz]of [[1,0],[-1,0],[0,1],[0,-1]]){const x=j.x+dx*(j.radius+.35)-dz*.95,z=j.z+dz*(j.radius+.35)+dx*.95,y=this.height(this.world,x,z);this.v.box(this.signalGroup,x,y+1.05,z,.055,2.1,.055,'#555d58');this.v.box(this.signalGroup,x,y+2.05,z,.18,.52,.18,'#202b28');const entry={axis:dx?'x':'z',indices:[]};for(let k=0;k<3;k++){dummy.position.set(x+dx*.11,y+2.22-k*.16,z+dz*.11);dummy.updateMatrix();bulbs.setMatrixAt(instance,dummy.matrix);bulbs.setColorAt(instance,new THREE.Color('#304139'));entry.indices.push(instance++);}this.signalEntries.push(entry);}
